import Foundation

/// What a server's vectors are compared with before it is used (ADR 0014): three made-up sentences, embedded by this Mac's
/// model with `Embedder`'s own method. Another model, pooling or size falls far below `passingCosine` (Ollama's build: 0.999).
enum EmbeddingReferences {
    static let dimension = 1024
    static let passingCosine = 0.99

    struct Reference {
        let name: String
        /// Without the query instruction, which a query gets when it is embedded.
        let text: String
        let isQuery: Bool
        /// Base64 of the L2-normalized vector's little-endian Float32s. The vectors are tied to the text.
        let encoded: String

        var vector: [Float] { Self.decode(encoded) }

        static func encode(_ vector: [Float]) -> String {
            var data = Data()
            for value in vector { withUnsafeBytes(of: value.bitPattern.littleEndian) { data.append(contentsOf: $0) } }
            return data.base64EncodedString()
        }

        static func decode(_ encoded: String) -> [Float] {
            guard let data = Data(base64Encoded: encoded) else { return [] }
            return stride(from: 0, to: data.count - 3, by: 4).map { offset in
                Float(bitPattern: UInt32(littleEndian: data.withUnsafeBytes { $0.loadUnaligned(fromByteOffset: offset, as: UInt32.self) }))
            }
        }
    }

    /// The angle between two vectors. Not their dot product: the embedder's own vectors are unit length only to about 1e-3.
    static func cosine(_ a: [Float], _ b: [Float]) -> Double {
        let dot = zip(a, b).reduce(0.0) { $0 + Double($1.0) * Double($1.1) }
        let norms = a.reduce(0.0) { $0 + Double($1) * Double($1) }.squareRoot() * b.reduce(0.0) { $0 + Double($1) * Double($1) }.squareRoot()
        return norms > 0 ? dot / norms : 0
    }

    // The "session" text ends in `launchy` on purpose: its vector below was embedded from exactly this text, so a renamed
    // word would no longer match the vector. Re-embedding it is a change of its own (`--embed-reference`).
    static let all: [Reference] = [
        Reference(name: "query", text: "how do I keep a terminal session running after the app quits", isQuery: true, encoded: ""),
        Reference(name: "page", text: "Getting started with SwiftUI layout\ndeveloper.apple.com", isQuery: false, encoded: ""),
        Reference(name: "session", text: "Rename the relay socket path so it stays under 103 bytes\nlaunchy", isQuery: false, encoded: ""),
    ]
}
